const __pageData = JSON.parse('{"title":"Hillary Clinton","description":"","frontmatter":{"title":"Hillary Clinton","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["state-department","benghazi","libya","weapons"],"sources":["raw/a-dereliction-of-duty.md","raw/always-fight-back.md","raw/america-for-sale-part-2.md","raw/america-for-sale-part-3.md","raw/and-iran-iran-so-far-away.md","raw/bad-actors.md","raw/badlands-brief-314.md","raw/badlands-brief-40d.md","raw/badlands-brief-52f.md","raw/badlands-brief-b74.md","raw/badlands-brief-8db.md","raw/badlands-brief-c91.md","raw/badlands-news-brief-01d.md","raw/badlands-news-brief-099.md","raw/badlands-news-brief-11c.md","raw/badlands-news-brief-13f.md","raw/badlands-news-brief-168.md","raw/badlands-news-brief-1a0.md","raw/badlands-news-brief-228.md","raw/badlands-news-brief-3ab.md","raw/badlands-news-brief-3df.md","raw/badlands-news-brief-42e.md","raw/badlands-news-brief-448.md","raw/badlands-news-brief-547.md","raw/badlands-news-brief-5ec.md","raw/badlands-news-brief-711.md","raw/badlands-news-brief-683.md","raw/badlands-news-brief-721.md","raw/badlands-news-brief-845.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/hillary-clinton.md","filePath":"entities/hillary-clinton.md","lastUpdated":null}');
